import{_ as i,o as s,c as e,a0 as t}from"./chunks/framework.l456sJqm.js";const k=JSON.parse('{"title":"青龙面板脚本","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"qinglong/index.md","filePath":"qinglong/index.md","lastUpdated":1783220091000}'),l={name:"qinglong/index.md"};function o(n,a,h,r,d,c){return s(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="青龙面板脚本" tabindex="-1">青龙面板脚本 <a class="header-anchor" href="#青龙面板脚本" aria-label="Permalink to &quot;青龙面板脚本&quot;">​</a></h1><p>MT 论坛青龙自动签到助手，支持多账号自动签到、概率签到、Cookie 缓存、消息提醒、异常通知。</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>为防止脚本大量使用对论坛造成影响，没有发帖，也没有声张，不建议在公开场合讨论。</p></div><h2 id="功能亮点" tabindex="-1">功能亮点 <a class="header-anchor" href="#功能亮点" aria-label="Permalink to &quot;功能亮点&quot;">​</a></h2><ul><li><strong>多账号支持</strong>：一次配置，批量自动签到</li><li><strong>智能概率签到</strong>：自定义时间段内概率递增签到，避免固定时间打卡风控</li><li><strong>自动缓存 Cookie</strong>：首次登录缓存 Cookie，之后复用</li><li><strong>论坛新消息提醒</strong>：自动检测未读消息并推送</li><li><strong>自定义通知时间</strong>：仅在指定时段发送通知</li><li><strong>异常自动处理</strong>：Cookie 过期自动清空，下次运行重新登录</li><li><strong>完整日志记录</strong>：执行状态一目了然</li></ul><h2 id="环境变量配置" tabindex="-1">环境变量配置 <a class="header-anchor" href="#环境变量配置" aria-label="Permalink to &quot;环境变量配置&quot;">​</a></h2><p>青龙面板 → 环境变量 → 新建变量，<strong>必填 1 个，选填 2 个</strong>。</p><h3 id="_1-必选-账号配置-mtbbs-accounts" tabindex="-1">1. 必选：账号配置（<code>mtbbs_accounts</code>） <a class="header-anchor" href="#_1-必选-账号配置-mtbbs-accounts" aria-label="Permalink to &quot;1. 必选：账号配置（`mtbbs_accounts`）&quot;">​</a></h3><p>格式为 JSON 数组，支持多账号：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;username&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;账号1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;password&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;密码1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;username&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;账号2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;password&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;密码2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><h3 id="_2-可选-消息提醒时间段-mtbbs-message-time" tabindex="-1">2. 可选：消息提醒时间段（<code>mtbbs_message_time</code>） <a class="header-anchor" href="#_2-可选-消息提醒时间段-mtbbs-message-time" aria-label="Permalink to &quot;2. 可选：消息提醒时间段（`mtbbs_message_time`）&quot;">​</a></h3><p>仅在该时段发送青龙通知，格式：<code>开始小时-结束小时</code>，多时段用逗号分隔。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>8-12,18-22</span></span></code></pre></div><ul><li>示例：<code>9-21</code> 代表每天 9 点 ~ 21 点才发送通知</li><li>不配置则<strong>全天不发送通知</strong>，只挂机</li></ul><h3 id="_3-可选-概率签到时间段-mtbbs-sign-time" tabindex="-1">3. 可选：概率签到时间段（<code>mtbbs_sign_time</code>） <a class="header-anchor" href="#_3-可选-概率签到时间段-mtbbs-sign-time" aria-label="Permalink to &quot;3. 可选：概率签到时间段（`mtbbs_sign_time`）&quot;">​</a></h3><p>在该时段内<strong>概率递增签到</strong>，格式同上。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0-23</span></span></code></pre></div><ul><li>概率规则：越接近结束时间，签到概率越高</li><li>不配置则<strong>不自动签到</strong></li><li>配置 <code>0-23</code> 为全天概率签到</li></ul><h2 id="快速部署" tabindex="-1">快速部署 <a class="header-anchor" href="#快速部署" aria-label="Permalink to &quot;快速部署&quot;">​</a></h2><ol><li>青龙面板 → 脚本管理 → 新建脚本（如 <code>mt_bbs.py</code>）</li><li>粘贴 <a href="https://raw.githubusercontent.com/qcxs/mtbbs/main/qinglong/qcxs_mtbbs.py" target="_blank" rel="noreferrer">qcxs_mtbbs.py</a> 完整代码并保存</li><li>配置环境变量（至少配置账号变量）</li><li>添加定时任务：命令填 <code>task mt_bbs.py</code>，建议定时 <code>0 8-22/2 * * *</code></li></ol><h2 id="定时建议" tabindex="-1">定时建议 <a class="header-anchor" href="#定时建议" aria-label="Permalink to &quot;定时建议&quot;">​</a></h2><ul><li>执行频率：每 2 小时运行一次</li><li>推荐定时：<code>0 8,20,32,44,56 * * * ?</code>（始终保持在线）</li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="提示登录失败" tabindex="-1">提示登录失败 <a class="header-anchor" href="#提示登录失败" aria-label="Permalink to &quot;提示登录失败&quot;">​</a></h3><ul><li>检查账号密码是否正确</li><li>确认 MT 论坛账号无异常</li><li>不支持验证码、安全提问</li></ul><h3 id="频繁提示-cookie-过期" tabindex="-1">频繁提示 Cookie 过期 <a class="header-anchor" href="#频繁提示-cookie-过期" aria-label="Permalink to &quot;频繁提示 Cookie 过期&quot;">​</a></h3><ul><li>手动登录论坛后，删除缓存文件或清空环境变量重新登录</li><li>尽量不要在多处同时使用相同账号签到</li></ul><h3 id="不发送通知" tabindex="-1">不发送通知 <a class="header-anchor" href="#不发送通知" aria-label="Permalink to &quot;不发送通知&quot;">​</a></h3><ul><li>检查是否配置 <code>mtbbs_message_time</code> 变量</li><li>确认当前时间在通知时段内</li><li>检查青龙通知渠道是否正常</li></ul><h2 id="文件说明" tabindex="-1">文件说明 <a class="header-anchor" href="#文件说明" aria-label="Permalink to &quot;文件说明&quot;">​</a></h2><ul><li>脚本文件：<code>qinglong/qcxs_mtbbs.py</code></li><li>运行后自动创建 <code>cache</code> 目录，存储账号 Cookie 与签到记录</li></ul>',31)])])}const u=i(l,[["render",o]]);export{k as __pageData,u as default};
